select ec.id, ec.parent_id as commentId, ec.user_id as userId, u1.name as userName, u1.avatar as userAvatar, ec.target_user_id as targetUserId, u2.name as targetUserName, ec.target_reply_id as targetReplyId, ec.content, ec.like_count as likeCount, ec.is_author as isAuthor, ec.hidden, ec.create_time as createTime from experience_comment ec left join user u1 on ec.user_id = u1.id left join user u2 on ec.target_user_id = u2.id where ec.parent_id in
#{parentId}
and (ec.hidden = 0 or ec.user_id = #{currentUserId}) order by ec.parent_id, ec.create_time asc

